import{_ as t,o,c as s,a2 as a}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"End-to-end suites","description":"","frontmatter":{},"headers":[],"relativePath":"dev/e2e-suites.md","filePath":"dev/e2e-suites.md"}'),r={name:"dev/e2e-suites.md"};function d(i,e,n,c,l,h){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="end-to-end-suites" tabindex="-1">End-to-end suites <a class="header-anchor" href="#end-to-end-suites" aria-label="Permalink to &quot;End-to-end suites&quot;">​</a></h1><p>The deep tests that gate a release. All of them drive a real QEMU boot through pexpect on the serial console; the 2.1.0 matrix below is what the release evidence quotes (real outputs, skip counts declared).</p><h2 id="the-2-1-0-verification-matrix" tabindex="-1">The 2.1.0 verification matrix <a class="header-anchor" href="#the-2-1-0-verification-matrix" aria-label="Permalink to &quot;The 2.1.0 verification matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Gate</th><th>Tool</th></tr></thead><tbody><tr><td>1</td><td>Host unit tests (<code>make test</code>)</td><td><code>tools/run_host_tests.py</code></td></tr><tr><td>2</td><td>Watchdog/logging/health E2E</td><td><code>tools/wp12_watchdog_logging_e2e.py</code></td></tr><tr><td>3</td><td>TUI command surface E2E</td><td><code>tools/wp10_tui_e2e.py</code></td></tr><tr><td>4</td><td>Chinese console E2E</td><td><code>tools/wp10_chinese_e2e.py</code></td></tr><tr><td>5</td><td>TUI desktop apps E2E</td><td><code>tools/wp10_tuiqa_apps_e2e.py</code></td></tr><tr><td>6</td><td>Native desktop E2E</td><td><code>tools/wp10_native_e2e.py</code></td></tr><tr><td>7</td><td>L1 per-app record (2.1.0)</td><td>every <code>l1apps/</code> program executed via <code>run</code> from ush, one record row per app</td></tr></tbody></table><h2 id="host-unit-tests-tools-run-host-tests-py" tabindex="-1">Host unit tests - tools/run_host_tests.py <a class="header-anchor" href="#host-unit-tests-tools-run-host-tests-py" aria-label="Permalink to &quot;Host unit tests - tools/run_host_tests.py&quot;">​</a></h2><p>19 harnesses compile L0 components host-side and run them: multiboot2 parser, crypto (BN/EC/RSA/X.509/AEAD/X25519), TLS 1.3 key schedule, TCP congestion control, block-512 gate, SCSI, IR, camera, wifi, bluetooth... <strong>17 PASS + 2 SKIP-FIXTURE</strong> without the openssl-generated fixtures (rsa/x509; with fixtures present they run for real - declare whichever state applied).</p><h2 id="watchdog-logging-health-e2e-tools-wp12-watchdog-logging-e2e-py" tabindex="-1">Watchdog/logging/health E2E - tools/wp12_watchdog_logging_e2e.py <a class="header-anchor" href="#watchdog-logging-health-e2e-tools-wp12-watchdog-logging-e2e-py" aria-label="Permalink to &quot;Watchdog/logging/health E2E - tools/wp12_watchdog_logging_e2e.py&quot;">​</a></h2><p>14 scenarios (S1-S14). The two that matter most:</p><ul><li><strong>S12 (Intel TCO)</strong>: q35 + <code>-no-reboot</code>; asserts the TCO discovery line (<code>Intel TCO found: PMBASE=... TCOBASE=...</code>), arms the watchdog, starves it, asserts the REAL reset and the second boot.</li><li><strong>S13 (ACPI WDAT)</strong>: same shape through the WDAT table entries.</li></ul><p>Plus klog write/flush/rotate/filter chains (threshold 4096 -&gt; <code>kernel.log</code> + <code>kernel.log.1</code> real generation), watchdog policy kill (a starver task is killed with a log record while the kernel survives), and health (JSON export validity, 3-spinner CPU alarm <code>CPU-LOCKED</code> with the kernel alive).</p><h2 id="tui-chinese-desktop-app-native-suites" tabindex="-1">TUI / Chinese / desktop-app / native suites <a class="header-anchor" href="#tui-chinese-desktop-app-native-suites" aria-label="Permalink to &quot;TUI / Chinese / desktop-app / native suites&quot;">​</a></h2><p><code>tools/wp10_tui_e2e.py</code> drives the L0 TUI command surface from <code>oc&gt;</code>; <code>tools/wp10_chinese_e2e.py</code> the CJK console; the <code>tuiqa</code>/<code>native</code> suites drive the desktop apps (files/editor/ panel/terminal + the native editor/file-manager upgrades) starting from the ring-3 <code>ush&gt;</code> prompt - the 2.x boot-flow adaptation.</p><h2 id="l1-per-app-record-2-1-0-addition" tabindex="-1">L1 per-app record (2.1.0 addition) <a class="header-anchor" href="#l1-per-app-record-2-1-0-addition" aria-label="Permalink to &quot;L1 per-app record (2.1.0 addition)&quot;">​</a></h2><p>The formal L1 application set is small and honest: <strong>ush</strong> (the only <code>OC_L1_APP_DECL</code> application) plus the 36 embedded test programs in <code>l1apps/</code>. The per-app record boots the release ISO, starts each program via <code>run &lt;name&gt;</code> from ush, and notes the observed output. Evidence lives in <code>evidence/</code> with the suite logs.</p><h2 id="regression-battery-v1-era-reference-tools-run-fix4-regression-py" tabindex="-1">Regression battery (v1-era, reference) - tools/run_fix4_regression.py <a class="header-anchor" href="#regression-battery-v1-era-reference-tools-run-fix4-regression-py" aria-label="Permalink to &quot;Regression battery (v1-era, reference) - tools/run_fix4_regression.py&quot;">​</a></h2><p>28 checks from the 1.0.0 era: boot banner, boot-complete, exception self-test 3/3, command count 233 (the v1 single-prompt world), uname tag forms, heaptest, fstest, cryptotest, crashlog, l1test, and every <code>run &lt;userprog&gt;</code>. Its command-count and prompt-flow assertions predate the v2 ring-3 split - it is kept for reference and its <code>run &lt;userprog&gt;</code> section is covered by the L1 per-app record instead.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 tools/run_fix4_regression.py build/opencube.iso out.log</span></span></code></pre></div><h2 id="ssh-https-suites-available-not-standard-gates" tabindex="-1">SSH / HTTPS suites (available, not standard gates) <a class="header-anchor" href="#ssh-https-suites-available-not-standard-gates" aria-label="Permalink to &quot;SSH / HTTPS suites (available, not standard gates)&quot;">​</a></h2><p><code>tools/ssh_mainstream_test.py</code> + <code>tools/sshd_test.py</code> (paramiko client against the in-guest sshd, host keys seeded on /etc via <code>host_keygen_etc</code>) and <code>tools/run_fix4_https_e2e.py</code> against <code>tools/https_test_server.py</code>. They need a seeded <code>etc.img</code> (<code>make etc.img</code>) and network fixtures; run them when touching the net stack.</p><h2 id="the-etc-volume-fixture" tabindex="-1">The /etc volume fixture <a class="header-anchor" href="#the-etc-volume-fixture" aria-label="Permalink to &quot;The /etc volume fixture&quot;">​</a></h2><p>SSH and HTTPS suites assume a seeded <code>etc.img</code>. Build it once per test cycle:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make etc.img          # 32 MiB FAT32 + opencube.conf</span></span>
<span class="line"><span># then inside a first boot: host_keygen_etc (writes SSH keys)</span></span></code></pre></div><p>The QEMU <code>run-*</code> make targets attach it automatically.</p>`,23)])])}const g=t(r,[["render",d]]);export{u as __pageData,g as default};
